BEGIN TRANSACTION;

-- Safe optimistic update with row lock
UPDATE accounts 
SET balance = balance - 500.00, updated_at = CURRENT_TIMESTAMP
WHERE id = 'acc-101' AND balance >= 500.00;

INSERT INTO audit_log (account_id, action, amount, logged_at)
VALUES ('acc-101', 'WITHDRAWAL', 500.00, CURRENT_TIMESTAMP);

COMMIT;
